.sc-tw :root{
            --amber-light: lch(70% 0.15 45);
            --pink-accent: lch(60% 0.20 330);
            --glass-border: linear-gradient(135deg, rgba(255, 255, 255, 0.15), rgba(255, 255, 255, 0.02));
            --glass-bg: linear-gradient(145deg, rgba(20, 20, 25, 0.4), rgba(10, 10, 15, 0.1));
        }.sc-tw html{
            scroll-behavior: smooth;
            background-color: black;
        }.sc-tw{
            margin: 0;
            overflow-x: hidden;
            color: white;
            background: black;
            min-height: 100vh;
        }.sc-tw .radial-mask-video{
            -webkit-mask-image: radial-gradient(circle at center, black 30%, transparent 90%);
            mask-image: radial-gradient(circle at center, black 30%, transparent 90%);
            mix-blend-mode: screen;
            opacity: 0.9;
        }.sc-tw .lab-glass{
            background: var(--glass-bg);
            backdrop-filter: blur(40px) brightness(1.1);
            -webkit-backdrop-filter: blur(40px) brightness(1.1);
            border-radius: 2.5rem;
            box-shadow: inset 0 0 1px 1px rgba(255, 255, 255, 0.05), 0 20px 40px rgba(0, 0, 0, 0.4);
            transition: all 0.6s cubic-bezier(0.16, 1, 0.3, 1);
            position: relative;
            overflow: hidden;
        }.sc-tw .lab-glass::before{
            content: '';
            position: absolute;
            inset: 0;
            border-radius: inherit;
            padding: 1px;
            background: var(--glass-border);
            -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
            -webkit-mask-composite: xor;
            mask-composite: exclude;
            pointer-events: none;
        }.sc-tw .bioluminescent-btn{
            background: linear-gradient(135deg, lch(70% 0.15 45 / 0.2), lch(70% 0.15 45 / 0.05));
            border-radius: 999px;
            position: relative;
            overflow: hidden;
            transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
            backdrop-filter: blur(20px);
            border: 1px solid lch(70% 0.15 45 / 0.3);
            box-shadow: inset 0 0 20px lch(70% 0.15 45 / 0.1), 0 0 15px lch(70% 0.15 45 / 0.05);
        }.sc-tw .bioluminescent-btn:hover{
            transform: scale(1.04);
            box-shadow: inset 0 0 40px lch(70% 0.15 45 / 0.4), 0 0 40px lch(70% 0.15 45 / 0.2);
            border-color: lch(70% 0.15 45 / 0.6);
        }.sc-tw .light-bleed{
            text-shadow: 0 0 25px lch(70% 0.15 45 / 0.5), 0 0 60px lch(70% 0.15 45 / 0.3);
        }.sc-tw .golden-thread{
            position: fixed;
            top: 0;
            left: 0;
            height: 2px;
            background: linear-gradient(90deg, transparent, lch(70% 0.15 45), lch(60% 0.20 330), transparent);
            box-shadow: 0 0 15px lch(70% 0.15 45);
            z-index: 100;
            width: 0%;
            transition: width 0.1s ease-out;
        }

        @keyframes float {0%{
                transform: translateY(0px) rotate(0deg);
            }50%{
                transform: translateY(-15px) rotate(1deg);
            }100%{
                transform: translateY(0px) rotate(0deg);
            }
        }.sc-tw .floating-element{
            animation: float 8s ease-in-out infinite;
        }.sc-tw .reveal{
            opacity: 0;
            transform: translateY(40px) scale(0.98);
            filter: blur(15px);
            transition: all 1.2s cubic-bezier(0.16, 1, 0.3, 1);
        }.sc-tw .reveal.active{
            opacity: 1;
            transform: translateY(0) scale(1);
            filter: blur(0);
